import { site } from '~/utils/site'

interface SeoInput {
  title: string
  description: string
  path: string
  /** path under /og (1200×630 JPEG generated by scripts/optimise_media.py) */
  ogImage: string
  ogImageAlt: string
  type?: 'website' | 'article'
  jsonLd?: Record<string, unknown>[]
}

export function useSiteUrl() {
  return useRuntimeConfig().public.siteUrl.replace(/\/$/, '')
}

/** The studio as a schema.org entity; referenced by @id from every page. */
export function organizationLd(base: string) {
  return {
    '@type': ['Organization', 'ProfessionalService'],
    '@id': `${base}/#organization`,
    'name': site.name,
    'alternateName': 'Lon Visuals',
    'url': `${base}/`,
    'logo': `${base}/logo.png`,
    'image': `${base}/og/home.jpg`,
    'email': site.email,
    'description': 'Lōn Visuals is a strategic brand and visual communication studio in Amman, Jordan, helping organizations communicate with clarity and impact through brand strategy, visual identity, communication design and brand experience.',
    'slogan': 'We translate brands into visual language',
    'address': { '@type': 'PostalAddress', 'addressLocality': site.city, 'addressCountry': site.countryCode },
    'areaServed': ['Jordan', 'Saudi Arabia', 'Morocco', 'Middle East and North Africa'],
    'knowsAbout': ['Brand strategy', 'Visual identity', 'Brand systems', 'Creative direction', 'Communication design', 'Print and editorial design', 'Brand experience'],
    'knowsLanguage': ['en', 'ar'],
    'sameAs': site.socials.map(s => s.href),
  }
}

export function useSeo(input: SeoInput) {
  const base = useSiteUrl()
  const url = `${base}${input.path}`
  const image = `${base}/og/${input.ogImage}`
  useSeoMeta({
    title: input.title,
    description: input.description,
    ogTitle: input.title,
    ogDescription: input.description,
    ogUrl: url,
    ogType: input.type ?? 'website',
    ogImage: image,
    ogImageWidth: 1200,
    ogImageHeight: 630,
    ogImageAlt: input.ogImageAlt,
    ogLocale: 'en_US',
    twitterCard: 'summary_large_image',
    twitterTitle: input.title,
    twitterDescription: input.description,
    twitterImage: image,
    twitterImageAlt: input.ogImageAlt,
    robots: 'index, follow, max-image-preview:large, max-snippet:-1',
  })
  useHead({
    link: [{ rel: 'canonical', href: url }],
    script: [{
      type: 'application/ld+json',
      key: 'ld',
      innerHTML: JSON.stringify({ '@context': 'https://schema.org', '@graph': input.jsonLd ?? [] }),
    }],
  })
}
